#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *next;
};

/* 头插法建表：依次插入 1、2、3，得到 3 -> 2 -> 1 -> NULL */
struct Node *insertHead(struct Node *head, int value) {
    struct Node *newNode = (struct Node *)malloc(sizeof(struct Node));
    if (newNode == NULL) {
        return head;            /* 分配失败：不改动原链表 */
    }
    newNode->data = value;
    newNode->next = head;       /* 先接：新结点抓住旧链表 */
    head = newNode;             /* 后断：头指针改指向新结点 */
    return head;
}

/* 遍历输出，用临时指针 p 前进，保留 head 不变 */
void printList(struct Node *head) {
    struct Node *p = head;
    while (p != NULL) {
        printf("%d -> ", p->data);
        p = p->next;
    }
    printf("NULL\n");
}

int main(void) {
    struct Node *head = NULL;
    head = insertHead(head, 1);
    head = insertHead(head, 2);
    head = insertHead(head, 3);
    printList(head);            /* 输出：3 -> 2 -> 1 -> NULL */
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node *next;
};

/* 头插法：把值 value 插入到链表首部，返回新的头指针 */
struct Node *insertHead(struct Node *head, int value) {
    struct Node *newNode = (struct Node *)malloc(sizeof(struct Node));
    if (newNode == NULL) {
        return head;            /* 分配失败，保持原链表不变 */
    }
    newNode->data = value;
    newNode->next = head;       /* 第一步：新结点先接住旧链表 */
    head = newNode;             /* 第二步：头指针再改指向新结点 */
    return head;
}

/* 遍历输出：3 -> 2 -> 1 -> NULL */
void printList(struct Node *head) {
    struct Node *p = head;
    while (p != NULL) {
        printf("%d -> ", p->data);
        p = p->next;
    }
    printf("NULL\n");
}

int main(void) {
    struct Node *head = NULL;
    head = insertHead(head, 1);
    head = insertHead(head, 2);
    head = insertHead(head, 3);
    printList(head);            /* 输出：3 -> 2 -> 1 -> NULL */
    return 0;
}
